for path in ['/tmp', '/run']:
    if os.path.exists(path):
        print(f"\nSockets in {path}:")
        for item in os.listdir(path):
            full_path = os.path.join(path, item)
            if os.path.islink(full_path) or (os.stat(full_path).st_mode & 0o170000 != 0):  # symlink or socket
                try:
                    st = os.stat(full_path)
                    if stat.S_ISSOCK(st.st_mode):
                        print(f"  {item} (socket)")
                except:
                    pass

import socket

# Try to connect to various potential ARC service ports
